def remove_my_list(title_id: int, profile: dict = Depends(current_profile)):
    with db() as c:
        row = c.execute("DELETE FROM my_list WHERE profile_id=%s AND title_id=%s RETURNING id",
                        (profile["id"], title_id)).fetchone()
    if not row:
