:root {
  --bg: #141414;
  --red: #e50914;
  --red-hover: #c11119;
  --card: #181818;
  --muted: #b3b3b3;
  --dim: #808080;
  --pad: 3.5vw;
  --gap: 0.45vw;
  --display: 'Anton', 'Bebas Neue', Impact, sans-serif;
  --ui: 'Inter', 'Helvetica Neue', Helvetica, Arial, sans-serif;
}
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body { background: var(--bg); color: #fff; font-family: var(--ui); -webkit-font-smoothing: antialiased; overflow-x: hidden; }
body.modal-open { overflow: hidden; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; color: inherit; background: none; border: 0; cursor: pointer; padding: 0; }
button:disabled { opacity: .6; cursor: default; }
img { display: block; }
.icon { display: inline-flex; align-items: center; justify-content: center; flex: none; }
.icon svg { display: block; }
.muted { color: var(--muted); }
.small { font-size: 13px; }
.dot { display: inline-block; width: 4px; height: 4px; border-radius: 50%; background: #646464; margin: 0 .55em; vertical-align: middle; }
.spinner { width: 54px; height: 54px; border-radius: 50%; border: 4px solid rgba(229,9,20,.25); border-top-color: var(--red); animation: spin 0.9s linear infinite; margin: 60px auto; }
.boot { min-height: 100vh; display: grid; place-items: center; }
@keyframes spin { to { transform: rotate(360deg); } }
@keyframes fadein { from { opacity: 0 } to { opacity: 1 } }

/* ---------- buttons ---------- */
.btn-red { display: inline-flex; align-items: center; justify-content: center; gap: 10px; background: var(--red); color: #fff; font-weight: 600; border-radius: 4px; padding: 10px 22px; font-size: 16px; transition: background .2s; }
.btn-red:hover { background: var(--red-hover); }
.btn-red.sm { padding: 7px 16px; font-size: 14px; font-weight: 600; }
.btn-red.lg { padding: 0 26px; height: 58px; font-size: 24px; font-weight: 600; }
.btn-red.block { width: 100%; height: 48px; font-size: 17px; }
.btn-white, .btn-grey { display: inline-flex; align-items: center; gap: 10px; border-radius: 4px; padding: 10px 22px; font-size: 16px; font-weight: 600; }
.btn-white { background: #fff; color: #000; }
.btn-white:hover { background: rgba(255,255,255,.8); }
.btn-grey { background: rgba(109,109,110,.7); color: #fff; }
.btn-grey:hover { background: rgba(109,109,110,.45); }
.btn-grey.sm { padding: 6px 14px; font-size: 14px; }
.circle-btn { width: 42px; height: 42px; border-radius: 50%; border: 2px solid rgba(255,255,255,.55); background: rgba(42,42,42,.6); display: inline-flex; align-items: center; justify-content: center; color: #fff; transition: border-color .15s, background .15s; flex: none; }
.circle-btn:hover { border-color: #fff; background: rgba(255,255,255,.1); }
.circle-btn.lg { width: 50px; height: 50px; }
.circle-btn.white { background: #fff; color: #000; border-color: #fff; }
.circle-btn.white:hover { background: rgba(255,255,255,.8); }
.circle-btn.rated { border-color: #fff; }
.push-right { margin-left: auto; }
.mute-btn { width: 44px; height: 44px; border-radius: 50%; border: 1px solid rgba(255,255,255,.7); color: #fff; background: rgba(0,0,0,.2); display: inline-flex; align-items: center; justify-content: center; }
.mute-btn:hover { background: rgba(255,255,255,.12); }
.mute-btn.sm { width: 36px; height: 36px; position: absolute; right: 14px; bottom: 14px; }

/* ---------- header ---------- */
.app-header { position: fixed; top: 0; left: 0; right: 0; z-index: 50; height: 88px; display: flex; align-items: center; padding: 0 var(--pad); background: linear-gradient(180deg, rgba(0,0,0,.75) 10%, rgba(0,0,0,0)); transition: background .35s; }
.app-header.scrolled { background: rgb(20,20,20); }
.wordmark { height: 25px; width: auto; margin-right: 26px; }
.primary-nav { display: flex; align-items: center; gap: 4px; }
.nav-pill { font-size: 17.5px; color: #e5e5e5; padding: 11px 18px; border-radius: 24px; transition: color .2s, background .2s; white-space: nowrap; }
.nav-pill:hover { color: #b3b3b3; }
.nav-pill.active { background: rgba(109,109,110,.65); color: #fff; font-weight: 600; }
.header-right { margin-left: auto; display: flex; align-items: center; gap: 22px; }
.icon-btn { color: #fff; display: inline-flex; padding: 6px; }
.search-box { display: flex; align-items: center; position: relative; }
.search-box.open { background: rgba(0,0,0,.75); border: 1px solid #fff; padding: 2px 6px; }
.search-box input { background: transparent; border: 0; outline: 0; color: #fff; font-size: 15px; width: 230px; font-family: inherit; }
.search-clear { color: #fff; display: inline-flex; padding: 4px; }
.kids-link { display: inline-flex; align-items: center; gap: 10px; color: #e5e5e5; font-size: 15px; }
.kids-link:hover { color: #fff; }
.profile-btn { display: flex; align-items: center; gap: 10px; }
.avatar { border-radius: 4px; display: block; }
.caret { display: inline-flex; color: #fff; transition: transform .2s; }
.caret.up { transform: rotate(180deg); }
.dropdown { position: absolute; top: calc(100% + 14px); right: 0; background: rgba(28,28,28,.97); border: 1px solid rgba(255,255,255,.08); border-radius: 12px; box-shadow: 0 10px 40px rgba(0,0,0,.6); animation: fadein .15s; z-index: 60; }
.notif, .profile-menu { position: relative; }
.account-menu { width: 278px; padding: 14px 0 8px; }
.am-item { display: flex; align-items: center; gap: 16px; width: 100%; padding: 11px 18px; font-size: 17px; color: #fff; text-align: left; }
.am-item:hover span { text-decoration: underline; }
.am-ico { width: 36px; display: inline-flex; justify-content: center; color: #e5e5e5; }
.am-sep { height: 1px; background: rgba(255,255,255,.15); margin: 8px 0; }
.am-signout { padding: 14px 18px; }
.notif-menu { width: 380px; max-height: 70vh; overflow: auto; padding: 8px 0; }
.notif-head { padding: 10px 16px; font-weight: 600; color: #e5e5e5; border-bottom: 1px solid rgba(255,255,255,.1); }
.notif-empty { padding: 18px 16px; color: var(--muted); }
.notif-item { display: flex; gap: 14px; padding: 12px 16px; width: 100%; text-align: left; border-bottom: 1px solid rgba(255,255,255,.06); }
.notif-item:hover { background: rgba(255,255,255,.06); }
.notif-item img { width: 112px; height: 63px; object-fit: cover; border-radius: 4px; }
.notif-item > span { display: flex; flex-direction: column; gap: 3px; font-size: 14px; }
.notif-item small { color: var(--muted); }

/* ---------- page shell ---------- */
.app-shell { min-height: 100vh; display: flex; flex-direction: column; }
.page { flex: 1; }
.app-footer { padding: 40px var(--pad) 30px; color: #757575; font-size: 13px; }
.toast { position: fixed; left: 50%; bottom: 32px; transform: translateX(-50%); background: #fff; color: #141414; padding: 12px 22px; border-radius: 6px; font-weight: 600; z-index: 400; box-shadow: 0 8px 30px rgba(0,0,0,.5); animation: fadein .2s; }

/* ---------- billboard ---------- */
.inset-wrap { padding: 97px var(--pad) 0; }
.billboard { position: relative; overflow: hidden; background: #000; }
.billboard.inset { border-radius: 20px; height: min(42.7vw, 82vh); min-height: 460px; box-shadow: 0 20px 60px rgba(0,0,0,.6); }
.billboard.full { height: 56.25vw; max-height: 100vh; min-height: 560px; }
.billboard.empty { background: #1a1a1a; }
.bb-img, .bb-video { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.bb-video { opacity: 0; transition: opacity .8s; }
.bb-video.on { opacity: 1; }
.bb-video.done { opacity: 0; }
.bb-shade { position: absolute; inset: 0; background: linear-gradient(77deg, rgba(0,0,0,.6) 0%, rgba(0,0,0,0) 60%); }
.billboard.full .bb-shade { background: linear-gradient(77deg, rgba(0,0,0,.6) 0%, rgba(0,0,0,0) 70%), linear-gradient(180deg, rgba(20,20,20,0) 70%, rgba(20,20,20,.6) 85%, #141414 100%); }
.bb-content { position: absolute; left: 44px; bottom: 42px; width: 40%; z-index: 2; }
.billboard.full .bb-content { left: var(--pad); bottom: 27%; width: 36%; }
.bb-title { font-family: var(--display); font-weight: 400; font-size: clamp(40px, 5.4vw, 108px); line-height: .95; margin: 0 0 18px; text-transform: uppercase; letter-spacing: .5px; text-shadow: 2px 2px 12px rgba(0,0,0,.45); }
.bb-meta { font-size: 18px; font-weight: 500; margin-bottom: 14px; color: #fff; }
.bb-synopsis { font-size: 17px; line-height: 1.45; margin: 0 0 26px; color: #fff; text-shadow: 1px 1px 3px rgba(0,0,0,.5); display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.bb-actions { display: flex; gap: 14px; }
.btn-play { display: inline-flex; align-items: center; gap: 12px; background: #fff; color: #000; font-size: 21px; font-weight: 600; padding: 0 28px 0 24px; height: 54px; border-radius: 28px; transition: background .2s; }
.btn-play:hover { background: rgba(255,255,255,.8); }
.btn-play.rect { border-radius: 4px; height: 58px; font-size: 24px; padding: 0 40px 0 32px; }
.btn-info { display: inline-flex; align-items: center; gap: 12px; background: rgba(109,109,110,.7); color: #fff; font-size: 21px; font-weight: 600; padding: 0 26px; height: 54px; border-radius: 28px; }
.billboard.inset .btn-info .icon { display: none; }
.billboard.full .btn-play, .billboard.full .btn-info { border-radius: 4px; height: 58px; font-size: 23px; }
.btn-info:hover { background: rgba(109,109,110,.45); }
.bb-side { position: absolute; right: 0; z-index: 2; display: flex; align-items: center; gap: 12px; }
.billboard.inset .bb-side { top: 40px; right: 44px; flex-direction: column; align-items: flex-end; bottom: 40px; justify-content: space-between; }
.billboard.full .bb-side { bottom: 32%; }
.bb-maturity { background: rgba(51,51,51,.6); border-left: 3px solid #dcdcdc; padding: 10px 70px 10px 16px; font-size: 21px; }
.bb-flag { display: inline-flex; align-items: center; gap: 8px; font-size: 15px; font-weight: 600; }
.bb-flag .icon { color: var(--red); }
.section-head { position: absolute; top: 88px; left: var(--pad); z-index: 3; display: flex; align-items: center; gap: 48px; }
.section-head h1 { font-size: 40px; font-weight: 600; margin: 0; }
.genres-menu { position: relative; }
.genres-btn { display: inline-flex; align-items: center; gap: 40px; border: 1px solid #fff; background: #000; padding: 5px 12px; font-size: 18px; }
.genres-drop { position: absolute; top: 100%; left: 0; margin-top: 2px; display: grid; grid-auto-flow: column; gap: 2px 36px; background: rgba(0,0,0,.92); border: 1px solid rgba(255,255,255,.15); padding: 12px 12px; z-index: 20; white-space: nowrap; }
.genres-drop a { font-size: 15.5px; line-height: 27px; }
.genres-drop a:hover { text-decoration: underline; }

/* ---------- rows ---------- */
.rows { padding: 34px 0 20px; position: relative; z-index: 2; }
.rows.overlap { margin-top: -11vw; }
.rows.top-pad { padding-top: 130px; }
.row { margin-bottom: 3.2vw; padding: 0 var(--pad); }
.row-head { display: flex; align-items: flex-end; justify-content: space-between; margin-bottom: 12px; }
.row-title { font-size: clamp(18px, 1.46vw, 28px); font-weight: 600; margin: 0; display: flex; align-items: center; gap: 12px; }
.row-link { display: inline-flex; align-items: baseline; gap: 14px; }
.row-link .explore { font-size: 14px; color: #54b9c5; opacity: 0; transform: translateX(-10px); transition: all .3s; }
.row-link:hover .explore { opacity: 1; transform: none; }
.row-pages { display: flex; gap: 2px; padding-bottom: 6px; }
.row-pages i { display: block; width: 18px; height: 2px; background: #4d4d4d; }
.row-pages i.on { background: #aaa; }
.row-viewport { position: relative; margin: 0 calc(-1 * var(--pad)); }
.row-track { display: flex; gap: var(--gap); overflow-x: auto; scroll-snap-type: x mandatory; scrollbar-width: none; padding: 0 var(--pad); scroll-padding: 0 var(--pad); }
.row-track::-webkit-scrollbar { display: none; }
.row-arrow { position: absolute; top: 0; bottom: 0; width: calc(var(--pad) - 4px); z-index: 4; background: rgba(20,20,20,.55); color: #fff; display: flex; align-items: center; justify-content: center; opacity: 0; transition: opacity .2s, background .2s; }
.row-viewport:hover .row-arrow { opacity: 1; }
.row-arrow:hover { background: rgba(20,20,20,.8); }
.row-arrow.left { left: 0; border-radius: 0 4px 4px 0; }
.row-arrow.right { right: 0; border-radius: 4px 0 0 4px; }
.row-empty { color: var(--muted); font-size: 15px; margin: 6px 0 0; }
.skeleton-track { overflow: hidden; }
.card-skel { flex: none; width: calc((100vw - 2 * var(--pad) - 5 * var(--gap)) / 6); aspect-ratio: 16/9; background: #222; border-radius: 4px; animation: pulse 1.4s ease-in-out infinite; }
@keyframes pulse { 50% { opacity: .5 } }
.beta { border: 2px solid #8e44e8; border-radius: 6px; font-size: 12px; letter-spacing: 6px; padding: 3px 4px 3px 10px; font-weight: 700; }

/* ---------- cards ---------- */
.title-card { position: relative; flex: none; width: calc((100vw - 2 * var(--pad) - 5 * var(--gap)) / 6); aspect-ratio: 16 / 9; border-radius: 4px; overflow: hidden; background: #222; scroll-snap-align: start; text-align: left; }
.row-lg .title-card { width: calc((100vw - 2 * var(--pad) - 4 * var(--gap)) / 5); aspect-ratio: 16/9; border-radius: 6px; }
.title-card img { width: 100%; height: 100%; object-fit: cover; transition: transform .3s; }
.title-card:hover img { transform: scale(1.03); }
.title-card::after { content: ''; position: absolute; inset: 0; background: linear-gradient(180deg, rgba(0,0,0,0) 45%, rgba(0,0,0,.65) 100%); pointer-events: none; }
.card-title { position: absolute; left: 10px; right: 46px; bottom: 9px; z-index: 1; font-family: var(--display); font-size: clamp(14px, 1.35vw, 26px); line-height: 1; text-transform: uppercase; text-shadow: 1px 1px 6px rgba(0,0,0,.7); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.top10-badge { position: absolute; top: 0; right: 4px; z-index: 2; width: 27px; height: 36px; background: var(--red); color: #fff; font-weight: 800; font-size: 15px; line-height: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; letter-spacing: -.5px; border-radius: 0 0 0 2px; }
.top10-badge small { font-size: 7.5px; letter-spacing: .3px; }
.top10-badge.static { position: static; display: inline-flex; margin-right: 10px; vertical-align: middle; }
.ribbon { position: absolute; left: 50%; bottom: 0; transform: translateX(-50%); z-index: 2; background: var(--red); color: #fff; font-size: clamp(10px, .75vw, 14px); font-weight: 700; padding: 3px 8px 2px; border-radius: 3px 3px 0 0; white-space: nowrap; }
.title-card .ribbon + .card-title, .title-card .card-title { bottom: 26px; }
.card-progress { position: absolute; left: 10%; right: 10%; bottom: 8px; height: 3px; background: rgba(128,128,128,.7); z-index: 3; }
.card-progress span { display: block; height: 100%; background: var(--red); }

.ranked-card { position: relative; flex: none; width: calc((100vw - 2 * var(--pad) - 5 * var(--gap)) / 6); aspect-ratio: 1.4 / 1; display: flex; justify-content: flex-end; scroll-snap-align: start; }
.rank-num { position: absolute; left: -2%; bottom: -6%; font-family: var(--ui); font-weight: 900; font-size: calc(14.5vw * .9); line-height: 1; letter-spacing: -1.2vw; color: #141414; -webkit-text-stroke: 4px #595959; z-index: 0; }
.ranked-card img { position: relative; z-index: 1; width: 50%; height: 100%; object-fit: cover; border-radius: 0 4px 4px 0; }
.ranked-card .ribbon { left: 75%; }

.title-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 4.4vw var(--gap); }
.title-grid .title-card { width: 100%; }

/* hover preview */
.preview { position: absolute; z-index: 120; background: var(--card); border-radius: 8px; box-shadow: 0 6px 30px rgba(0,0,0,.75); overflow: visible; animation: grow .2s ease-out; }
@keyframes grow { from { transform: scale(.7); opacity: .4 } to { transform: none; opacity: 1 } }
.preview-media { position: relative; aspect-ratio: 16/9; overflow: hidden; border-radius: 8px 8px 0 0; cursor: pointer; }
.preview-media img, .preview-media video { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.preview-media video { opacity: 0; transition: opacity .5s; }
.preview-media video.on { opacity: 1; }
.preview-title { position: absolute; left: 16px; bottom: 14px; right: 64px; font-family: var(--display); font-size: 30px; line-height: 1; text-transform: uppercase; text-shadow: 1px 1px 8px rgba(0,0,0,.7); }
.preview-info { padding: 16px 18px 20px; }
.preview-actions { display: flex; align-items: center; gap: 8px; margin-bottom: 14px; }
.meta-line { display: flex; align-items: center; gap: 9px; font-size: 16px; color: #bcbcbc; margin-bottom: 12px; }
.maturity { border: 1px solid rgba(255,255,255,.4); padding: 1px 7px; font-size: .95em; color: #fff; display: inline-block; line-height: 1.3; }
.hd { border: 1px solid rgba(255,255,255,.4); border-radius: 3px; font-size: 11px; padding: 0 5px; font-weight: 600; line-height: 1.5; }
.tag-line { font-size: 16px; color: #fff; display: flex; flex-wrap: wrap; align-items: center; }
.thumb-wrap { position: relative; }
.rate-pop { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); display: flex; gap: 4px; padding: 5px 8px; background: #232323; border-radius: 40px; box-shadow: 0 4px 16px rgba(0,0,0,.6); z-index: 5; animation: fadein .15s; }
.rate-opt { position: relative; width: 44px; height: 44px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; color: #fff; }
.rate-opt:hover { background: rgba(255,255,255,.12); }
.rate-opt.on { background: rgba(255,255,255,.22); }
.rate-opt .tip { position: absolute; bottom: calc(100% + 14px); left: 50%; transform: translateX(-50%); background: #e6e6e6; color: #000; font-size: 17px; font-weight: 600; padding: 6px 14px; border-radius: 4px; white-space: nowrap; opacity: 0; pointer-events: none; transition: opacity .15s; }
.rate-opt .tip::after { content: ''; position: absolute; top: 100%; left: 50%; transform: translateX(-50%); border: 7px solid transparent; border-top-color: #e6e6e6; }
.rate-opt:hover .tip { opacity: 1; }

/* ---------- detail modal ---------- */
.modal-backdrop { position: fixed; inset: 0; z-index: 200; background: rgba(0,0,0,.7); overflow-y: auto; animation: fadein .2s; }
.detail-modal { position: relative; width: min(1085px, 94vw); margin: 36px auto 40px; background: var(--card); border-radius: 8px; overflow: hidden; box-shadow: 0 10px 50px rgba(0,0,0,.8); min-height: 300px; }
.modal-close { position: absolute; top: 16px; right: 16px; z-index: 10; width: 40px; height: 40px; border-radius: 50%; background: #181818; color: #fff; display: inline-flex; align-items: center; justify-content: center; }
.modal-close:hover { background: #2a2a2a; }
.modal-loading, .modal-error { padding: 80px 40px; text-align: center; }
.dm-hero { position: relative; aspect-ratio: 16 / 9; max-height: 610px; width: 100%; background: #000; }
.dm-hero img, .dm-hero video { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.dm-hero video { opacity: 0; transition: opacity .8s; }
.dm-hero video.on { opacity: 1; }
.dm-shade { position: absolute; inset: 0; background: linear-gradient(0deg, #181818 0%, rgba(24,24,24,0) 40%); }
.dm-hero-content { position: absolute; left: 3em; bottom: 9%; right: 40%; z-index: 2; }
.dm-title { font-family: var(--display); font-weight: 400; font-size: clamp(36px, 5vw, 72px); line-height: .95; margin: 0 0 26px; text-transform: uppercase; color: var(--red); text-shadow: 2px 2px 10px rgba(0,0,0,.5); }
.dm-actions { display: flex; align-items: center; gap: 10px; }
.dm-mute { position: absolute; right: 3em; bottom: 10%; z-index: 2; }
.dm-body { padding: 4px 3em 40px; }
.dm-cols { display: grid; grid-template-columns: 2fr 1fr; gap: 2em; }
.dm-meta { display: flex; align-items: center; gap: 9px; color: #bcbcbc; font-size: 17px; margin: 14px 0 6px; }
.dm-meta .dim { color: #bcbcbc; }
.dm-meta2 { margin-bottom: 14px; font-size: 16px; }
.dm-top10 { display: flex; align-items: center; font-size: 21px; font-weight: 600; margin-bottom: 12px; }
.dm-synopsis { font-size: 18px; line-height: 1.6; margin: 10px 0 0; }
.dm-right p { font-size: 15px; line-height: 1.5; margin: 14px 0; word-break: break-word; }
.label { color: #777; }
.dm-right a:hover { text-decoration: underline; }
.episodes { margin-top: 40px; }
.ep-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px; }
.ep-head h3, .mlt h3, .dm-about h3 { font-size: 26px; font-weight: 600; margin: 0; }
.season-static { font-size: 18px; color: #ddd; }
.season-select { position: relative; }
.season-btn { display: inline-flex; align-items: center; gap: 40px; font-size: 19px; background: #242424; border: 1px solid #4d4d4d; border-radius: 4px; padding: 11px 20px; }
.season-list { position: absolute; right: 0; top: calc(100% + 2px); list-style: none; margin: 0; padding: 6px 0; background: #242424; border: 1px solid #4d4d4d; border-radius: 4px; min-width: 100%; z-index: 5; }
.season-list button { display: block; width: 100%; text-align: left; padding: 10px 20px; font-size: 17px; }
.season-list button:hover, .season-list button.on { background: #414141; }
.ep-sub { font-size: 15px; margin-bottom: 16px; }
.episode { display: flex; align-items: center; gap: 0; width: 100%; padding: 26px 24px; border-bottom: 1px solid #404040; border-radius: 4px; text-align: left; }
.episode:first-of-type { border-top: 1px solid #404040; }
.episode.current, .episode:hover { background: #333; }
.ep-num { width: 52px; flex: none; font-size: 26px; color: #d2d2d2; text-align: center; }
.ep-thumb { position: relative; width: 170px; aspect-ratio: 16/9; flex: none; border-radius: 4px; overflow: hidden; margin: 0 18px 0 6px; }
.ep-thumb img { width: 100%; height: 100%; object-fit: cover; }
.ep-play { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; opacity: 0; background: rgba(0,0,0,.35); transition: opacity .2s; }
.episode:hover .ep-play { opacity: 1; }
.ep-info { flex: 1; display: flex; flex-direction: column; gap: 8px; }
.ep-top { display: flex; justify-content: space-between; font-size: 17px; }
.ep-syn { font-size: 15px; color: #d2d2d2; line-height: 1.45; }
.mlt { margin-top: 44px; }
.mlt-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-top: 18px; }
.mlt-card { background: #2f2f2f; border-radius: 4px; overflow: hidden; text-align: left; }
.mlt-card:hover { background: #3a3a3a; }
.mlt-img { position: relative; aspect-ratio: 16/9; }
.mlt-img img { width: 100%; height: 100%; object-fit: cover; }
.mlt-img .card-title { bottom: 8px; }
.mlt-body { padding: 14px; }
.mlt-meta { display: flex; gap: 10px; align-items: center; color: #bcbcbc; margin-bottom: 8px; font-size: 15px; }
.mlt-body p { font-size: 14px; color: #d2d2d2; line-height: 1.4; margin: 0; display: -webkit-box; -webkit-line-clamp: 4; -webkit-box-orient: vertical; overflow: hidden; }
.dm-about { margin-top: 44px; padding-top: 10px; }
.dm-about h3 { font-weight: 400; margin-bottom: 16px; }
.dm-about p { font-size: 15px; margin: 8px 0; }

/* rate dialog */
.rate-dialog-backdrop { position: fixed; inset: 0; z-index: 300; background: rgba(0,0,0,.6); backdrop-filter: blur(10px); display: flex; align-items: center; justify-content: center; animation: fadein .2s; }
.rate-dialog { position: relative; width: min(960px, 92vw); border-top: 5px solid var(--red); padding: 70px 40px 36px; text-align: center; }
.rd-close { position: absolute; top: 14px; right: 14px; color: #fff; }
.rate-dialog h2 { font-size: clamp(28px, 2.6vw, 46px); font-weight: 600; margin: 10px 0 18px; }
.rd-sub { font-size: 21px; color: #ccc; margin: 0 0 44px; }
.rd-options { display: flex; justify-content: center; gap: 4vw; margin-bottom: 24px; }
.rd-opt { display: flex; flex-direction: column; align-items: center; gap: 18px; width: 200px; font-size: 17px; line-height: 1.35; color: #fff; padding: 14px 6px; border-radius: 10px; border: 2px solid transparent; }
.rd-opt:hover { background: rgba(255,255,255,.07); }
.rd-opt.on { border-color: #fff; background: rgba(255,255,255,.12); }
.rd-status { color: #aaa; font-size: 14px; min-height: 18px; }
.rd-ok { background: #1f1f1f; border-radius: 4px; padding: 11px 26px; font-weight: 700; font-size: 17px; margin-top: 18px; }
.rd-ok:hover { background: #333; }

/* ---------- grid pages ---------- */
.grid-page { padding: 110px var(--pad) 40px; min-height: 80vh; }
.page-title { font-size: clamp(28px, 2.2vw, 42px); font-weight: 500; margin: 6px 0 44px; }
.search-label { color: #aaa; font-size: 17px; margin: 30px 0 30px; }
.search-label b { color: #fff; }
.empty-state { text-align: center; padding: 70px 20px; color: #ddd; max-width: 620px; margin: 0 auto; }
.empty-state.left { text-align: left; margin: 0; padding: 30px 0; max-width: 820px; }
.empty-state h3 { font-size: 24px; margin: 0 0 12px; }
.empty-state p { font-size: 16px; line-height: 1.5; color: #b3b3b3; }
.empty-actions { display: flex; gap: 12px; justify-content: center; margin-top: 22px; }
.lang-head { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 20px; margin-bottom: 40px; }
.lang-head .page-title { margin: 0; }
.lang-prefs { display: flex; align-items: center; gap: 14px; font-size: 15px; flex-wrap: wrap; }
.lang-dd { position: relative; }
.lang-dd-btn { display: inline-flex; align-items: center; justify-content: space-between; gap: 30px; min-width: 240px; border: 1px solid #fff; background: #000; padding: 6px 12px; font-size: 19px; letter-spacing: .3px; }
.lang-dd-list { position: absolute; top: 100%; left: 0; right: 0; list-style: none; margin: 0; padding: 6px 0; background: rgba(0,0,0,.92); border: 1px solid rgba(255,255,255,.15); z-index: 30; max-height: 60vh; overflow: auto; }
.lang-dd-list button { display: block; width: 100%; text-align: left; padding: 5px 12px; font-size: 16px; }
.lang-dd-list button:hover, .lang-dd-list button.on { text-decoration: underline; }
.lang-dd-list small { color: #888; }
.genre-page { position: relative; min-height: 100vh; }
.genre-head { position: relative; z-index: 3; display: flex; align-items: baseline; gap: 14px; padding: 104px var(--pad) 18px; background: #000; }
.genre-head .crumb { font-size: 20px; color: #9a9a9a; }
.genre-head .crumb:hover { color: #fff; }
.crumb-sep { color: #9a9a9a; font-size: 22px; }
.genre-head h1 { margin: 0; font-size: 42px; font-weight: 500; }
.genre-bg { position: absolute; left: 0; right: 0; top: 160px; height: 60vh; background-size: cover; background-position: center top; opacity: .35; mask-image: linear-gradient(180deg, #000 30%, transparent); -webkit-mask-image: linear-gradient(180deg, #000 30%, transparent); }
.genre-rows { padding-top: 60px; }
.games-page { padding-top: 0; }
.games-hero { padding: 180px var(--pad) 50px; background: linear-gradient(180deg, #23103a 0%, #141414 100%); }
.games-hero h1 { font-family: var(--display); font-weight: 400; font-size: 84px; margin: 0 0 12px; text-transform: uppercase; }
.games-meta { font-size: 18px; color: #ddd; }
.account-page .acct-card { background: #1c1c1c; border-radius: 8px; padding: 22px 26px; margin-bottom: 22px; max-width: 760px; }
.acct-card h2 { margin: 0 0 14px; font-size: 20px; }
.acct-card p { display: flex; gap: 20px; margin: 8px 0; }
.acct-card .label { width: 70px; }
.acct-profile { display: flex; align-items: center; gap: 14px; margin-bottom: 12px; }
.acct-profile span { flex: 1; }
.notfound { min-height: 100vh; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; gap: 14px; background: radial-gradient(circle, #2b2b2b, #000); }
.notfound h1 { font-size: 60px; margin: 30px 0 0; }

/* ---------- landing ---------- */
.landing { position: relative; min-height: 100vh; background: #000; overflow: hidden; }
.landing-collage { position: absolute; inset: -10% -10% auto; height: 105vh; overflow: hidden; perspective: 1200px; }
.collage-grid { display: grid; grid-template-columns: repeat(12, 1fr); gap: 14px; transform: rotateX(18deg) rotateZ(-14deg) scale(1.35) translateY(-8%); }
.collage-grid img { width: 100%; aspect-ratio: 2/3; object-fit: cover; border-radius: 8px; }
.landing-shade { position: absolute; inset: 0; height: 100vh; background: radial-gradient(ellipse at center, rgba(0,0,0,.55) 0%, rgba(0,0,0,.8) 100%), linear-gradient(180deg, rgba(0,0,0,.7) 0%, rgba(0,0,0,.15) 40%, rgba(0,0,0,.9) 100%); }
.landing-header { position: relative; z-index: 2; display: flex; align-items: center; justify-content: space-between; padding: 24px 8.5vw; }
.landing-logo { height: 46px; width: auto; }
.landing-header-right { display: flex; align-items: center; gap: 14px; }
.lang-select { display: inline-flex; align-items: center; gap: 6px; border: 1px solid rgba(255,255,255,.5); border-radius: 4px; padding: 4px 10px; background: rgba(0,0,0,.6); }
.lang-select select { background: transparent; color: #fff; border: 0; font-size: 16px; font-family: inherit; outline: 0; }
.lang-select option { color: #000; }
.lang-glyph { font-size: 13px; }
.landing-hero { position: relative; z-index: 2; text-align: center; padding: 15vh 20px 0; max-width: 900px; margin: 0 auto; min-height: 70vh; }
.landing-hero h1 { font-size: clamp(32px, 3.6vw, 64px); font-weight: 900; line-height: 1.18; margin: 0 auto 22px; max-width: 680px; }
.lh-sub { font-size: 21px; font-weight: 600; margin: 0 0 36px; }
.lh-cta { font-size: 17px; margin: 0 0 18px; }
.lh-form { display: flex; gap: 10px; justify-content: center; }
.lh-form input { width: 405px; height: 58px; border-radius: 4px; border: 1px solid rgba(128,128,128,.7); background: rgba(22,22,22,.7); color: #fff; padding: 0 16px; font-size: 17px; font-family: inherit; }
.landing-curve { position: relative; z-index: 2; height: 90px; margin-top: 30px; border-top: 3px solid transparent; border-radius: 50% 50% 0 0 / 100% 100% 0 0; background: linear-gradient(#000, #000) padding-box, linear-gradient(90deg, rgba(229,9,20,.2), #e50914 30%, #d6407a 70%, rgba(229,9,20,.2)) border-box; box-shadow: 0 -30px 60px rgba(70,20,110,.4) inset; }
.landing-banner { position: relative; z-index: 2; background: #000; padding: 0 8.5vw 60px; }
.banner-card { display: flex; align-items: center; gap: 22px; background: linear-gradient(90deg, #1b1a4a, #2c1650 60%, #36174d); border-radius: 16px; padding: 18px 28px; }
.banner-icon { font-size: 54px; }
.banner-card h3 { margin: 0 0 4px; font-size: 22px; }
.banner-card p { margin: 0; color: #ddd; }
.banner-card .btn-grey { margin-left: auto; white-space: nowrap; }

/* ---------- auth ---------- */
.auth-page { min-height: 100vh; display: flex; flex-direction: column; background: linear-gradient(180deg, #3c1416 0%, #1b0a0b 45%, #000 80%); }
.auth-header { padding: 22px 11vw; border-bottom: 1px solid rgba(255,255,255,.1); }
.auth-header.slim { border: 0; padding: 22px var(--pad); }
.auth-logo { height: 46px; width: auto; }
.auth-logo.sm { height: 30px; }
.auth-main { flex: 1; display: flex; justify-content: center; padding: 48px 20px; }
.auth-form { width: 490px; max-width: 100%; }
.auth-form h1 { font-size: 36px; font-weight: 700; margin: 0 0 10px; }
.auth-sub { font-size: 19px; color: #ccc; margin: 0 0 26px; }
.float-field { display: block; position: relative; border: 1px solid rgba(128,128,128,.8); border-radius: 4px; background: rgba(22,22,22,.7); padding: 8px 16px 6px; margin-bottom: 14px; }
.float-field span { display: block; font-size: 13px; color: #bbb; }
.float-field input { width: 100%; background: transparent; border: 0; outline: 0; color: #fff; font-size: 17px; padding: 4px 0; font-family: inherit; }
.float-field:focus-within { outline: 2px solid #fff; outline-offset: 1px; }
.auth-error { background: #d89d31; color: #000; padding: 12px 16px; border-radius: 4px; margin-bottom: 16px; font-size: 15px; }
.auth-switch { color: #b3b3b3; margin-top: 28px; font-size: 16px; }
.auth-switch a { color: #fff; font-weight: 600; }
.auth-switch a:hover { text-decoration: underline; }
.auth-demo { color: #8c8c8c; font-size: 13px; margin-top: 16px; }
.auth-footer { background: #161616; padding: 40px 11vw 60px; color: #b3b3b3; font-size: 16px; }

/* ---------- profiles ---------- */
.profiles-page { min-height: 100vh; background: #141414; }
.who { display: flex; flex-direction: column; align-items: center; padding-top: 12vh; }
.who h1 { font-size: clamp(32px, 3.5vw, 56px); font-weight: 500; margin: 0 0 30px; }
.who-grid { display: flex; gap: 2vw; flex-wrap: wrap; justify-content: center; }
.who-item { display: flex; flex-direction: column; align-items: center; gap: 14px; width: 160px; }
.who-av { position: relative; width: 160px; height: 160px; border-radius: 6px; outline: 3px solid transparent; transition: outline-color .15s; }
.who-item:hover .who-av { outline-color: #fff; }
.who-av svg { width: 100%; height: 100%; }
.who-av.add { display: flex; align-items: center; justify-content: center; font-size: 90px; color: #808080; font-weight: 200; }
.who-item:hover .who-av.add { background: #e5e5e5; color: #141414; }
.who-edit { position: absolute; inset: 0; background: rgba(0,0,0,.5); display: flex; align-items: center; justify-content: center; border-radius: 4px; }
.who-name { font-size: 19px; color: #808080; }
.who-item:hover .who-name { color: #e5e5e5; }
.manage-btn { margin-top: 60px; border: 1px solid #808080; color: #808080; padding: 10px 26px; font-size: 18px; letter-spacing: 2px; }
.manage-btn:hover { border-color: #fff; color: #fff; }
.manage-btn.done { background: #fff; color: #141414; border-color: #fff; font-weight: 600; }
.profile-editor { max-width: 740px; margin: 8vh auto 0; padding: 0 20px; }
.profile-editor h1 { font-size: 56px; font-weight: 400; margin: 0 0 6px; }
.pe-sub { color: #666; font-size: 18px; margin: 0; }
.pe-body { display: flex; gap: 28px; border-top: 1px solid #333; border-bottom: 1px solid #333; padding: 24px 0; margin: 18px 0 30px; }
.pe-body > svg { flex: none; }
.pe-fields { flex: 1; }
.pe-name { width: 100%; background: #666; border: 0; color: #fff; font-size: 18px; padding: 10px 12px; font-family: inherit; outline: 0; }
.pe-label { margin: 20px 0 10px; color: #ccc; }
.pe-avatars { display: flex; gap: 12px; flex-wrap: wrap; }
.pe-av { border-radius: 6px; outline: 3px solid transparent; }
.pe-av.on, .pe-av:hover { outline-color: #fff; }
.pe-kids { display: flex; gap: 10px; align-items: center; margin-top: 22px; color: #ccc; }
.pe-kids input { width: 22px; height: 22px; accent-color: #fff; }
.pe-actions { display: flex; gap: 18px; }
.pe-btn { border: 1px solid #808080; color: #808080; padding: 10px 26px; font-size: 17px; letter-spacing: 1.5px; text-transform: uppercase; }
.pe-btn:hover { border-color: #fff; color: #fff; }
.pe-btn.primary { background: #fff; color: #000; border-color: #fff; font-weight: 600; }
.pe-btn.primary:hover { background: var(--red); color: #fff; border-color: var(--red); }

/* ---------- player ---------- */
.player { position: fixed; inset: 0; background: #000; z-index: 500; overflow: hidden; }
.player.no-ui { cursor: none; }
.pl-video { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; background: #000; }
.pl-loading { position: absolute; inset: 0; display: grid; place-items: center; }
.pl-top { position: absolute; top: 0; left: 0; right: 0; padding: 22px 26px; display: flex; justify-content: space-between; transition: opacity .3s; z-index: 3; }
.pl-back { color: #fff; display: inline-flex; padding: 6px; transition: transform .15s; }
.pl-back:hover { transform: scale(1.15); }
.player.error .pl-back { position: absolute; top: 22px; left: 26px; }
.pl-error { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.pl-bottom { position: absolute; left: 0; right: 0; bottom: 0; padding: 0 26px 22px; background: linear-gradient(0deg, rgba(0,0,0,.75), rgba(0,0,0,0)); transition: opacity .3s; z-index: 3; }
.player.no-ui .pl-top, .player.no-ui .pl-bottom { opacity: 0; pointer-events: none; }
.pl-progress-row { display: flex; align-items: center; gap: 18px; padding-top: 30px; }
.pl-bar { position: relative; flex: 1; height: 5px; background: rgba(128,128,128,.6); cursor: pointer; touch-action: none; }
.pl-bar:hover { height: 8px; }
.pl-bar-buf { position: absolute; left: 0; top: 0; bottom: 0; background: rgba(200,200,200,.6); }
.pl-bar-fill { position: absolute; left: 0; top: 0; bottom: 0; background: var(--red); }
.pl-bar-knob { position: absolute; top: 50%; width: 18px; height: 18px; border-radius: 50%; background: var(--red); transform: translate(-50%, -50%); }
.pl-bar-tip { position: absolute; bottom: 20px; transform: translateX(-50%); background: rgba(0,0,0,.8); padding: 4px 8px; border-radius: 3px; font-size: 14px; pointer-events: none; }
.pl-remaining { font-size: 16px; min-width: 52px; text-align: right; }
.pl-controls { display: flex; align-items: center; margin-top: 18px; }
.pl-left, .pl-right { display: flex; align-items: center; gap: 30px; flex: 1; }
.pl-right { justify-content: flex-end; gap: 40px; }
.pl-btn { color: #fff; display: inline-flex; transition: transform .15s; }
.pl-btn:hover, .pl-btn.on { transform: scale(1.2); }
.pl-title { font-size: 20px; text-align: center; flex: 1.2; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pl-title span { color: #ddd; margin-left: 6px; }
.pl-vol { position: relative; display: inline-flex; }
.pl-vol-pop { position: absolute; bottom: 52px; left: 50%; transform: translateX(-50%); background: #262626; padding: 16px 12px; border-radius: 4px; }
.pl-vol-pop input { writing-mode: vertical-lr; direction: rtl; height: 120px; width: 24px; accent-color: var(--red); }
.pl-paused-info { position: absolute; left: 8vw; top: 26vh; max-width: 46vw; z-index: 2; animation: fadein .6s; pointer-events: none; }
.pl-paused-info button { pointer-events: auto; margin-top: 18px; }
.pl-watching { color: #ccc; font-size: 20px; margin: 0 0 8px; }
.pl-paused-info h1 { font-size: 54px; margin: 0 0 10px; font-weight: 700; }
.pl-paused-info h2 { font-size: 26px; margin: 0 0 14px; font-weight: 600; }
.pl-desc { font-size: 19px; line-height: 1.45; color: #ddd; }
.pl-ended { position: absolute; inset: 0; z-index: 2; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px; background: rgba(0,0,0,.6); animation: fadein .3s; }
.pl-ended h2 { font-size: 32px; margin: 0 0 16px; }
.pl-ended-actions { display: flex; gap: 14px; }
.pl-panel { position: absolute; right: 26px; bottom: 120px; z-index: 4; background: #262626; border-radius: 4px; padding: 20px 24px; box-shadow: 0 6px 30px rgba(0,0,0,.6); animation: fadein .15s; }
.pl-panel h3 { margin: 0 0 12px; font-size: 22px; }
.episodes-panel { width: min(520px, 90vw); max-height: 60vh; overflow: auto; }
.pl-ep { display: flex; gap: 16px; width: 100%; padding: 12px 10px; font-size: 17px; border-top: 1px solid #3a3a3a; text-align: left; }
.pl-ep:hover, .pl-ep.on { background: #3a3a3a; }
.pl-ep-n { color: #aaa; width: 60px; }
.pl-ep-name { flex: 1; }
.pl-ep-d { color: #aaa; }
.audio-panel { display: flex; gap: 60px; min-width: 460px; }
.pl-opt { display: flex; align-items: center; gap: 10px; font-size: 18px; padding: 6px 0; color: #fff; }

/* ---------- responsive ---------- */
@media (max-width: 1280px) {
  .nav-pill { font-size: 15px; padding: 9px 12px; }
}
@media (max-width: 1000px) {
  .primary-nav { overflow-x: auto; scrollbar-width: none; }
  .title-card, .card-skel, .ranked-card { width: calc((100vw - 2 * var(--pad) - 3 * var(--gap)) / 3.3); }
  .row-lg .title-card { width: calc((100vw - 2 * var(--pad)) / 2.3); }
  .title-grid { grid-template-columns: repeat(3, 1fr); }
  .bb-content, .billboard.full .bb-content { width: 80%; left: 24px; }
  .dm-cols { grid-template-columns: 1fr; }
  .mlt-grid { grid-template-columns: repeat(2, 1fr); }
  .kids-link span { display: none; }
}

