const { chromium } = require('playwright');
const B = 'http://127.0.0.1:5173';
(async () => {
  const b = await chromium.launch();
  const p = await b.newPage({ viewport: { width: 1600, height: 900 } });
  const errs = []; p.on('pageerror', e => errs.push('pageerror ' + e.message));
  p.on('console', m => { if (m.type() === 'error') errs.push('console ' + m.text()) });
  const log = (...a) => console.log(...a);
  await p.goto(B + '/');
  await p.fill('.lh-form input', `u${Date.now()}@test.com`); await p.click('.lh-form button');
  await p.waitForURL('**/signup**');
  await p.fill('input[autocomplete=name]', 'Tester'); await p.fill('input[type=password]', 'secret123');
  await p.click('button[type=submit]'); await p.waitForURL('**/profiles'); await p.waitForSelector('.who-name');
  log('profiles:', await p.$$eval('.who-name', e => e.map(x => x.textContent)));
  await p.click('text=Add Profile'); await p.fill('.pe-name', 'Second'); await p.click('.pe-av >> nth=3'); await p.click('text=Save');
  await p.waitForTimeout(600);
  log('after add:', await p.$$eval('.who-name', e => e.map(x => x.textContent)));
  // manage: rename Second
  await p.click('text=Manage Profiles'); await p.click('.who-item:has-text("Second")');
  await p.fill('.pe-name', 'Second Renamed'); await p.click('text=Save'); await p.waitForTimeout(500);
  log('after rename:', await p.$$eval('.who-name', e => e.map(x => x.textContent)));
  await p.click('text=Done');
  await p.click('.who-item >> nth=0'); await p.waitForURL('**/browse'); await p.waitForTimeout(1500);
  log('rows:', (await p.$$eval('.row-title', e => e.map(x => x.textContent))).length);
  await p.click('.row-track .title-card >> nth=0'); await p.waitForSelector('.detail-modal .dm-title');
  log('modal:', await p.textContent('.dm-title'));
  await p.click('.dm-actions [aria-label="Add to My List"]'); await p.waitForTimeout(600);
  log('toast:', await p.textContent('.toast').catch(() => null));
  await p.click('.dm-actions [aria-label="Rate this title"]'); await p.click('.rd-opt >> nth=2'); await p.waitForTimeout(400);
  log('rate:', await p.textContent('.rd-status')); await p.click('.rd-ok');
  await p.click('.modal-close');
  // hover card + list toggle from preview
  await p.hover('.row-track .title-card >> nth=2'); await p.waitForSelector('.preview', { timeout: 3000 });
  await p.click('.preview [aria-label="Add to My List"]'); await p.waitForTimeout(500);
  log('preview toggle toast:', await p.textContent('.toast').catch(() => null));
  await p.mouse.move(5, 5);
  await p.click('a.nav-pill:has-text("My List")'); await p.waitForTimeout(800);
  log('my list:', await p.$$eval('.grid-page .title-card', e => e.map(x => x.getAttribute('aria-label'))));
  await p.hover('.profile-btn'); await p.waitForTimeout(300);
  await p.click('.account-menu .am-item:has-text("Second")'); await p.waitForTimeout(800);
  await p.click('a.nav-pill:has-text("My List")'); await p.waitForTimeout(800);
  log('other profile:', await p.textContent('.empty-state h3').catch(() => 'none'));
  await p.click('[aria-label=Search]'); await p.keyboard.type('stranger'); await p.waitForTimeout(1200);
  log('search', await p.$$eval('.title-grid .title-card', e => e.map(x => x.getAttribute('aria-label'))));
  for (const path of ['/shows', '/movies', '/games', '/new', '/browse/languages', '/account']) {
    await p.goto(B + path); await p.waitForTimeout(700);
    log(path, 'h1/rows:', await p.$$eval('h1, .row-title', e => e.slice(0, 3).map(x => x.textContent)));
  }
  await p.goto(B + '/shows'); await p.click('.genres-btn'); await p.click('.genres-drop a >> nth=0'); await p.waitForTimeout(800);
  log('genre:', await p.textContent('.genre-head h1'));
  await p.goto(B + '/browse/languages'); await p.click('.lang-dd-btn >> nth=1'); await p.click('.lang-dd-list button:has-text("Korean")'); await p.waitForTimeout(800);
  log('korean:', await p.$$eval('.title-grid .title-card', e => e.length));
  await p.click('.lang-dd-btn >> nth=0'); await p.click('.lang-dd-list button:has-text("Dubbing")'); await p.waitForTimeout(400);
  log('dubbing:', await p.textContent('.empty-state h3'));
  await p.click('[aria-label=Notifications]'); await p.waitForTimeout(600);
  await p.click('.notif-item >> nth=0'); await p.waitForSelector('.dm-title'); log('notif opens modal:', await p.textContent('.dm-title'));
  await p.goto(B + '/browse?title=36'); await p.waitForSelector('.episode');
  await p.click('.episode >> nth=1'); await p.waitForURL('**/watch/**'); log('episode play url', p.url());
  await p.mouse.move(500, 500); await p.click('[aria-label="Episodes"]'); log('episodes panel:', await p.$$eval('.pl-ep', e => e.length));
  await p.click('[aria-label="Next episode"]'); await p.waitForTimeout(400); log('next ep url', p.url());
  await p.mouse.move(600, 500); await p.click('[aria-label="Back to browse"]'); await p.waitForTimeout(600); log('after back', p.url());
  await p.goto(B + '/nope'); log('404:', await p.textContent('h1'));
  await p.goto(B + '/browse'); await p.hover('.profile-btn'); await p.click('text=Sign out of Netflix'); await p.waitForURL('**/login'); log('signed out ok');
  await p.fill('input[type=email]', 'demo@netflix.local'); await p.fill('input[type=password]', 'wrong'); await p.click('button[type=submit]');
  await p.waitForSelector('.auth-error'); log('bad pw:', await p.textContent('.auth-error'));
  log('ERRORS:', errs.join('\n') || 'none');
  await b.close();
})().catch(e => { console.error('FAIL', e.message.slice(0, 600)); process.exit(1) });

