new="""// Small screens: the primary nav collapses into a "Browse" dropdown with the same links.
function MobileNav() {
  const location = useLocation()
  const [open, setOpen] = useState(false)
  const ref = useRef(null)
  useOutside(ref, () => setOpen(false))
  useEffect(() => setOpen(false), [location.pathname])
  const current = NAV.find(([to]) => to === location.pathname)
  return (
    <div className="mobile-nav" ref={ref}>
      <button className="mobile-nav-btn" aria-expanded={open} onClick={() => setOpen((o) => !o)}>
        {current ? current[1] : 'Browse'} <CaretDown />
      </button>
      {open && (
        <div className="dropdown mobile-nav-menu">
          {NAV.map(([to, label]) => (
            <NavLink key={to} to={to} end className={({ isActive }) => `mobile-nav-item ${isActive ? 'active' : ''}`}>{label}</NavLink>
          ))}
        </div>
      )}
    </div>
  )
}

export default function Header() {"""
