const { firefox } = require('playwright');
const B = 'http://127.0.0.1:5173';
const cw = (p) => p.evaluate(async () => (await fetch('/api/continue-watching', { headers: { Authorization: 'Bearer ' + localStorage.nf_token, 'X-Profile-Id': localStorage.nf_profile } })).json()).then(r => JSON.stringify(r.items.map(x => [x.name, x.progress_seconds])));
(async () => {
  const b = await firefox.launch(); const p = await b.newPage({ viewport: { width: 1600, height: 900 } });
  await p.goto(B + '/login'); await p.fill('input[type=email]', 'demo@netflix.local'); await p.fill('input[type=password]', 'netflix123');
  await p.click('button[type=submit]'); await p.waitForURL('**/profiles'); await p.waitForSelector('.who-name'); await p.click('.who-item >> nth=0'); await p.waitForURL('**/browse');
  // A) deep link, seek, browser-level back (page unload)
  await p.goto(B + '/watch/2'); await p.waitForTimeout(2500); await p.mouse.move(800, 400);
  await p.click('[aria-label="Back 10 seconds"]'); await p.click('[aria-label="Forward 10 seconds"]'); await p.waitForTimeout(300);
  console.log('A pos', await p.evaluate(() => document.querySelector('video').currentTime));
  await p.click('[aria-label="Back to browse"]'); await p.waitForTimeout(1200);
  console.log('A cw', await cw(p));
  // B) in-app: modal Play -> seek back to start -> +10 then -10... -> back
  await p.goto(B + '/browse?title=4'); await p.waitForSelector('.dm-actions .btn-play'); await p.click('.dm-actions .btn-play');
  await p.waitForURL('**/watch/4'); await p.waitForTimeout(2500); await p.mouse.move(800, 400);
  await p.click('[aria-label="Forward 10 seconds"]'); await p.waitForTimeout(300);
  console.log('B pos', await p.evaluate(() => document.querySelector('video').currentTime));
  await p.click('[aria-label="Back to browse"]'); await p.waitForTimeout(1000);
  console.log('B url', p.url(), 'cw', await cw(p));
  await b.close();
})().catch(e => { console.error('FAIL', e.message.slice(0, 400)); process.exit(1) });
